public enum PrivacyFilter {
    /// The marker password managers (1Password and others) put on a copied password.
    static let concealedType = "org.nspasteboard.ConcealedType"
    static let blockedTypes: Set<String> = [
        concealedType,
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
    ]
    /// `allowConcealed` is the user's opt-in to keep copied passwords; transient and
    /// auto-generated pasteboards are dropped regardless.
    public static func shouldStore(pasteboardTypes: Set<String>, allowConcealed: Bool = false) -> Bool {
        let blocked = allowConcealed ? blockedTypes.subtracting([concealedType]) : blockedTypes
        return pasteboardTypes.isDisjoint(with: blocked)
    }
}
